import{_ as l,C as c,c as h,o as a,a2 as s,b as o,w as t,a as n,G as i,ai as d}from"./chunks/framework.Bx7EIe62.js";const w=JSON.parse('{"title":"Core Objects","description":"","frontmatter":{"outline":[2,3]},"headers":[],"relativePath":"guides/concepts/core-objects.md","filePath":"guides/concepts/core-objects.md","lastUpdated":1788171555000}'),p={name:"guides/concepts/core-objects.md"};function f(u,e,m,g,y,b){const r=c("Mermaid");return a(),h("div",null,[e[2]||(e[2]=s('<h1 id="core-objects" tabindex="-1">Core Objects <a class="header-anchor" href="#core-objects" aria-label="Permalink to &quot;Core Objects&quot;">​</a></h1><p>Most integrations are built from a small number of objects. This guide explains what each one is, why it exists, and how they relate to each other. If you are looking for the definition of a single term, see the <a href="./../glossary.html">Glossary</a>.</p><p>A <strong>Client</strong> is the person you&#39;re working with. Each distinct reason for verifying them is created as a <strong>Case</strong> — the unit your team works and signs off. Within a case you send one or more <strong>Records</strong> to the client, each requesting something specific from them. A record contains one or more <strong>Steps</strong>: the individual checks or pieces of information you&#39;re asking for. Each record is linked into its case by a <strong>Case Item</strong>, which tracks what the case contains and when each record was added. A <strong>Record Template</strong> is a reusable blueprint that saves you rebuilding the same set of steps every time.</p>',3)),(a(),o(d,null,{default:t(()=>[i(r,{id:"mermaid-9",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20RT%5BRecord%20Template%5D%0A%20%20%20%20C%5BClient%5D%0A%20%20%20%20CA%5BCase%5D%0A%20%20%20%20CI%5BCase%20Item%5D%0A%20%20%20%20R%5BRecord%5D%0A%20%20%20%20S%5BStep%5D%0A%0A%20%20%20%20C%20--%3E%20CA%0A%20%20%20%20CA%20--%3E%20CI%0A%20%20%20%20CI%20--%3E%20R%0A%20%20%20%20C%20--%3E%20R%0A%20%20%20%20R%20--%3E%20S%0A%20%20%20%20RT%20-.blueprint.-%3E%20R%0A"})]),fallback:t(()=>e[0]||(e[0]=[n(" Loading... ")])),_:1})),e[3]||(e[3]=s('<p>Every case belongs to a client, and every step belongs to a record. Cases are the default structure, though a small number of legacy teams are not yet on this model. One important difference from the product: the API does not put records into cases for you — see <a href="#creating-a-record-inside-a-case-takes-two-calls">Creating a record inside a case takes two calls</a>.</p><h2 id="terminology" tabindex="-1">Terminology <a class="header-anchor" href="#terminology" aria-label="Permalink to &quot;Terminology&quot;">​</a></h2><p>The API and the Amiqus application use different names for the same things. The API terms are the ones used throughout this documentation and in every request and response.</p><table tabindex="0"><thead><tr><th style="text-align:left;">API term</th><th style="text-align:left;">Amiqus term</th><th style="text-align:left;">What it is</th></tr></thead><tbody><tr><td style="text-align:left;">Client</td><td style="text-align:left;">Person</td><td style="text-align:left;">The individual being verified.</td></tr><tr><td style="text-align:left;">Case</td><td style="text-align:left;">Case</td><td style="text-align:left;">A grouping of records covering a single process.</td></tr><tr><td style="text-align:left;">Record</td><td style="text-align:left;">Request</td><td style="text-align:left;">A set of steps sent to a client to complete.</td></tr><tr><td style="text-align:left;">Step</td><td style="text-align:left;">Check, document request, document transfer or form</td><td style="text-align:left;">One unit of work within a record.</td></tr><tr><td style="text-align:left;">Record template</td><td style="text-align:left;">Request template</td><td style="text-align:left;">A saved set of steps and settings used to create records.</td></tr></tbody></table><p>See the <a href="./../glossary.html">Glossary</a> for the full list, including files, documents and organisations.</p><h2 id="the-objects" tabindex="-1">The objects <a class="header-anchor" href="#the-objects" aria-label="Permalink to &quot;The objects&quot;">​</a></h2><h3 id="client" tabindex="-1">Client <a class="header-anchor" href="#client" aria-label="Permalink to &quot;Client&quot;">​</a></h3><p>A client is the person your team wants to engage with — a candidate, applicant, employee or customer. It holds their name, contact details and any information gathered about them over time.</p><p>A client is the anchor for everything else: records and cases both belong to a client, and a client persists across as many of them as you need. Create one with <a href="https://developers.amiqus.co/aqid/api-reference.html#tag/Clients/operation/post-clients" target="_blank" rel="noreferrer">Create a client</a>.</p><h3 id="record" tabindex="-1">Record <a class="header-anchor" href="#record" aria-label="Permalink to &quot;Record&quot;">​</a></h3><p>A record is a set of steps you ask a client to complete. It is the object your client actually interacts with: creating one produces a <code>perform_url</code> that the client opens in a browser to work through the steps.</p><p>Records carry an <code>email</code> and a <code>name</code> that are <strong>snapshots</strong> taken when the record was created, so they may differ from the client&#39;s current details if those have since changed. A record also has its own <code>status</code> reflecting how far the client has progressed, and an <code>expired_at</code> date after which it can no longer be completed.</p><p>Create one with <a href="https://developers.amiqus.co/aqid/api-reference.html#tag/Records/operation/post-records" target="_blank" rel="noreferrer">Create a record</a>.</p><h3 id="step" tabindex="-1">Step <a class="header-anchor" href="#step" aria-label="Permalink to &quot;Step&quot;">​</a></h3><p>A record consists of one or more steps, and a step is the smallest unit of work. Steps come in four kinds:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Step type</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><code>check.*</code></td><td style="text-align:left;">A verification performed by Amiqus or a provider, such as <code>check.identity</code>, <code>check.criminal_record</code> or <code>check.watchlist</code>.</td></tr><tr><td style="text-align:left;"><code>document.request</code></td><td style="text-align:left;">Asks the client to upload a document.</td></tr><tr><td style="text-align:left;"><code>document.transfer</code></td><td style="text-align:left;">Sends a document to the client to read or sign.</td></tr><tr><td style="text-align:left;"><code>form</code></td><td style="text-align:left;">Asks the client to answer a set of questions.</td></tr></tbody></table><p>Only one of each check type may be used within a single record. Steps are reviewed individually, and each review has its own status independent of the record. See <a href="https://developers.amiqus.co/aqid/api-reference.html#tag/Records/operation/get-records-id-steps" target="_blank" rel="noreferrer">List all steps for a record</a>.</p><h3 id="case" tabindex="-1">Case <a class="header-anchor" href="#case" aria-label="Permalink to &quot;Case&quot;">​</a></h3><p>A case represents one distinct reason for verifying a client — an onboarding, a contract renewal, a periodic re-verification — and groups the records that relate to it. It exists so that your team works and signs off the <em>reason</em>, not the person.</p><p>Without cases, a client who is checked twice two years apart has two unrelated records and no way to distinguish the first sign-off from the second. A case draws a boundary around one of those processes, gives it a <code>name</code> and optional <code>reference</code>, and gives your team a single status and a single place to review every result inside it.</p><p>Cases have their own <a href="https://developers.amiqus.co/aqid/api-reference.html#tag/Case-Assignees/operation/get-cases-id-assignees" target="_blank" rel="noreferrer">assignees</a> and a <a href="https://developers.amiqus.co/aqid/api-reference.html#tag/Cases/operation/get-cases-id-reviews" target="_blank" rel="noreferrer">review history</a> recording each status change and who made it. Create one with <a href="https://developers.amiqus.co/aqid/api-reference.html#tag/Cases/operation/post-cases" target="_blank" rel="noreferrer">Create a case</a>.</p><h3 id="case-item" tabindex="-1">Case item <a class="header-anchor" href="#case-item" aria-label="Permalink to &quot;Case item&quot;">​</a></h3><p>A case item is the membership link between a case and one record inside it. It carries an <code>entity</code> describing what it points to — an <code>id</code> and a <code>type</code>, currently always <code>record</code> — and its own <code>created_at</code>, recording when the record was <strong>added to the case</strong> rather than when the record itself was created.</p><p>You will rarely model case items directly, but they are how records are added to a case — see <a href="#adding-a-record-to-a-case">Adding a record to a case</a>.</p><h3 id="record-template" tabindex="-1">Record template <a class="header-anchor" href="#record-template" aria-label="Permalink to &quot;Record template&quot;">​</a></h3><p>A record template is a saved set of steps and settings, so you do not have to describe the same combination of steps on every request. Templates are configured by your team in Amiqus and are read-only over the API.</p><p>Pass a template ID when creating a record instead of listing steps individually, and optionally have the template&#39;s assignees applied to the new record automatically. See <a href="https://developers.amiqus.co/aqid/api-reference.html#tag/Templates/operation/get-templates-records" target="_blank" rel="noreferrer">List all record templates</a>.</p><h2 id="how-they-fit-together" tabindex="-1">How they fit together <a class="header-anchor" href="#how-they-fit-together" aria-label="Permalink to &quot;How they fit together&quot;">​</a></h2><h3 id="creating-a-record-inside-a-case-takes-two-calls" tabindex="-1">Creating a record inside a case takes two calls <a class="header-anchor" href="#creating-a-record-inside-a-case-takes-two-calls" aria-label="Permalink to &quot;Creating a record inside a case takes two calls&quot;">​</a></h3><p>Cases are created empty. There is no way to create a record and attach it to a case in a single request, and no case field on <a href="https://developers.amiqus.co/aqid/api-reference.html#tag/Records/operation/post-records" target="_blank" rel="noreferrer">Create a record</a>.</p>',30)),(a(),o(d,null,{default:t(()=>[i(r,{id:"mermaid-212",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20autonumber%0A%20%20%20%20participant%20Your%20App%0A%20%20%20%20participant%20Amiqus%0A%0A%20%20%20%20Your%20App-%3E%3EAmiqus%3A%20Create%20client%0A%20%20%20%20Amiqus--%3E%3EYour%20App%3A%20client%20id%0A%20%20%20%20Your%20App-%3E%3EAmiqus%3A%20Create%20case%20(name%2C%20client)%0A%20%20%20%20Amiqus--%3E%3EYour%20App%3A%20case%20id%0A%20%20%20%20Your%20App-%3E%3EAmiqus%3A%20Create%20record%20(client%2C%20steps%20or%20template)%0A%20%20%20%20Amiqus--%3E%3EYour%20App%3A%20record%20id%2C%20perform_url%0A%20%20%20%20Your%20App-%3E%3EAmiqus%3A%20Add%20record%20to%20case%20(PATCH%20case%20items)%0A%20%20%20%20Amiqus--%3E%3EYour%20App%3A%20case%20item%0A"})]),fallback:t(()=>e[1]||(e[1]=[n(" Loading... ")])),_:1})),e[4]||(e[4]=s(`<h3 id="adding-a-record-to-a-case" tabindex="-1">Adding a record to a case <a class="header-anchor" href="#adding-a-record-to-a-case" aria-label="Permalink to &quot;Adding a record to a case&quot;">​</a></h3><p>Records are attached after the fact with <a href="https://developers.amiqus.co/aqid/api-reference.html#tag/Case-Items/operation/patch-cases-id-items" target="_blank" rel="noreferrer">Update items for a case</a>, which merges the given items into the case&#39;s existing items:</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#89DDFF;">[</span></span>
<span class="line"><span style="color:#89DDFF;">    {</span></span>
<span class="line"><span style="color:#89DDFF;">        &quot;</span><span style="color:#C792EA;">id</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 8811</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#89DDFF;">        &quot;</span><span style="color:#C792EA;">type</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">record</span><span style="color:#89DDFF;">&quot;</span></span>
<span class="line"><span style="color:#89DDFF;">    }</span></span>
<span class="line"><span style="color:#89DDFF;">]</span></span></code></pre></div><p>The same call is how you attach a follow-up record to a case later on. A case can gain further records at any point.</p><h3 id="the-link-is-one-directional" tabindex="-1">The link is one-directional <a class="header-anchor" href="#the-link-is-one-directional" aria-label="Permalink to &quot;The link is one-directional&quot;">​</a></h3><p>You can traverse from a case to its records, by expanding <code>items</code> on a case or by listing its case items. <strong>You cannot traverse the other way.</strong> A record has no <code>case</code> property, and records cannot be filtered by case.</p><p>If your integration needs to know which case a record belongs to, store that association on your side when you make the call that creates it.</p><h3 id="case-status-and-record-status-are-different" tabindex="-1">Case status and record status are different <a class="header-anchor" href="#case-status-and-record-status-are-different" aria-label="Permalink to &quot;Case status and record status are different&quot;">​</a></h3><p>The two statuses answer different questions, are drawn from different enums, and do not track each other. A record&#39;s status describes how far one client has got through one set of steps. A case&#39;s status describes where your team is in reviewing the whole process.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Case status</th><th style="text-align:left;">Amiqus term</th><th style="text-align:left;">Meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>awaiting_response</code></td><td style="text-align:left;">Waiting for response</td><td style="text-align:left;">Awaiting a response from the client, a provider or another external party.</td></tr><tr><td style="text-align:left;"><code>action_required</code></td><td style="text-align:left;">Action required</td><td style="text-align:left;">Awaiting team member action to progress the case.</td></tr><tr><td style="text-align:left;"><code>reviewed_pending_decision</code></td><td style="text-align:left;">Reviewed</td><td style="text-align:left;">Every check has been reviewed; pending final approval or rejection.</td></tr><tr><td style="text-align:left;"><code>approved</code></td><td style="text-align:left;">Approved</td><td style="text-align:left;">Completed and approved.</td></tr><tr><td style="text-align:left;"><code>rejected</code></td><td style="text-align:left;">Rejected</td><td style="text-align:left;">Completed and rejected.</td></tr><tr><td style="text-align:left;"><code>on_hold</code></td><td style="text-align:left;">On hold</td><td style="text-align:left;">Inactive, on hold.</td></tr></tbody></table><p><code>pending</code> also appears in the enum but is deprecated.</p><p>Case status moves in response to the checks inside the case, and it is not necessarily linear: a case that reached <code>reviewed_pending_decision</code> returns to <code>awaiting_response</code> if a further record is sent to the client. Team members can also set a status manually. Do not assume a case only ever moves forwards.</p><p>Record statuses are a separate enum entirely — <code>pending</code>, <code>started</code>, <code>complete</code>, <code>waiting</code>, <code>paused</code> and others — documented on the <a href="https://developers.amiqus.co/aqid/api-reference.html#tag/Records/operation/get-records-id" target="_blank" rel="noreferrer">record object</a>.</p><h2 id="availability-of-cases" tabindex="-1">Availability of cases <a class="header-anchor" href="#availability-of-cases" aria-label="Permalink to &quot;Availability of cases&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Cases are the default, but the API will not apply them for you</p><p>Cases are the default structure for teams. A small number of legacy teams are not yet on this model and work with clients and records only; the cases endpoints are not available to them.</p><p>More important for your integration: <strong>a record you create through the API does not belong to a case until you explicitly add it.</strong> Records are never placed in a case automatically, even on a team that uses cases. Attach them with <a href="https://developers.amiqus.co/aqid/api-reference.html#tag/Case-Items/operation/patch-cases-id-items" target="_blank" rel="noreferrer">Update items for a case</a>, and store the association on your side if you need to look it up later.</p></div><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./pagination.html">Pagination</a> and <a href="./expandable-properties.html">Expandable Properties</a> — how to retrieve these objects efficiently.</li><li><a href="./../webhooks.html">Webhooks</a> — how to be notified when records and cases change.</li><li><a href="./../glossary.html">Glossary</a> — the full list of API terms and their Amiqus equivalents.</li></ul>`,17))])}const q=l(p,[["render",f]]);export{w as __pageData,q as default};
